component StudioDiagnostics {
    Column {
        width: 880; height: 360; padding: 24; gap: 10; background: state.theme.canvas;
        Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '06  /  ДИАГНОСТИКА И СТАТУС'; }
        Alert { width: 820; height: 70; tone: 'success'; text: 'Разметка проверена. Ошибок нет.'; description: 'StudioControls.ui'; }
        Alert { width: 820; height: 70; tone: 'warning'; text: 'Содержимое выходит за границы Frame'; description: 'Inspector.ui:24'; }
        Alert { width: 820; height: 70; tone: 'danger'; text: 'Ключ capton не найден. Возможно, caption?'; description: 'LargeButton.ui:8'; }
        StatusBar { width: 820; first: 'Сохранено'; second: 'Forma UI'; third: 'UTF-8'; }
    }
}

component StudioInspector {
    Column {
        width: 880; height: 360; padding: 24; gap: 10; background: state.theme.canvas;
        Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '04  /  ПОЛЯ ИНСПЕКТОРА'; }
        Row { gap: 12; height: 38;
            TextField { value: '18'; placeholder: 'Размер шрифта'; }
            SearchField { placeholder: 'Поиск свойства'; width: 240; }
            TextField { value: 'ошибка'; error: true; }
        }
        Row { gap: 12; height: 38;
            TableRow { width: 264; first: 'fontSize'; second: '18'; third: 'LargeButton'; }
            TableRow { width: 264; first: 'radius'; second: '5'; third: 'Button'; }
            TableRow { width: 264; first: 'width'; second: '160'; third: 'Экземпляр'; }
        }
    }
}

component StudioControls {
    Frame {
        width: 900; height: 780; background: state.theme.canvas;
        Scroll {
          Column {
            padding: 24; gap: 10;
            Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: 'FORMA STUDIO  /  КОНТРОЛЫ'; color: state.theme.text; fontSize: 18; }
            Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '01  /  ПАНЕЛЬ ИНСТРУМЕНТОВ'; }
            Row { gap: 8; height: 32;
                PrimaryButton { width: 130; text: 'Запустить'; clicked -> actions.run(); }
                SecondaryButton { width: 130; text: 'Открыть'; clicked -> actions.open(); }
                SecondaryButton { width: 130; text: 'Экспорт'; clicked -> actions.export(); }
                SecondaryButton { width: 130; text: 'Остановить'; disabled: true; }
                IconButton { icon: 'assets/plus.svg'; clicked -> actions.add(); }
                IconButton { icon: 'assets/search.svg'; clicked -> actions.search(); }
                IconButton { icon: 'assets/close.svg'; clicked -> actions.close(); }
            }
            Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '02  /  ВКЛАДКИ РЕДАКТОРА'; }
            Row { gap: 2; height: 36;
                TabButton { width: 170; text: 'SearchWindow.ui'; selected: true; clicked -> actions.selectTab(); }
                TabButton { width: 170; text: 'Button.ui •'; }
                TabButton { width: 170; text: 'tokens.ui'; }
                TabButton { width: 170; text: 'README.md'; disabled: true; }
            }
            Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '03  /  ДЕРЕВО ПРОЕКТА'; }
            Row { gap: 18; height: 90;
                Column { width: 270; gap: 2;
                    TreeItem { text: 'components'; branch: true; expanded: true; }
                    TreeItem { text: 'Button.ui'; branch: false; indent: 18; selected: true; }
                    TreeItem { text: 'TextField.ui'; branch: false; indent: 18; }
                }
                Column { width: 270; gap: 2;
                    TreeItem { text: 'ui'; branch: true; expanded: false; }
                    TreeItem { text: 'assets'; branch: true; expanded: true; }
                    TreeItem { text: 'search.svg'; branch: false; indent: 18; disabled: true; }
                }
            }
            Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '04  /  ПОЛЯ ИНСПЕКТОРА'; }
            Row { gap: 12; height: 38;
                TextField { value: '18'; placeholder: 'Размер шрифта'; }
                SearchField { placeholder: 'Поиск свойства'; width: 240; }
                TextField { value: 'ошибка'; error: true; }
            }
            Row { gap: 12; height: 38;
                TableRow { width: 264; first: 'fontSize'; second: '18'; third: 'LargeButton'; }
                TableRow { width: 264; first: 'radius'; second: '5'; third: 'Button'; }
                TableRow { width: 264; first: 'width'; second: '160'; third: 'Экземпляр'; }
            }
            Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '05  /  ПАРАМЕТРЫ ПРЕДПРОСМОТРА'; }
            Row { gap: 12; height: 32;
                Checkbox { text: 'Показать размеры'; checked: true; }
                Checkbox { text: 'Привязки к сетке'; }
                Checkbox { text: 'Только чтение'; checked: true; disabled: true; }
            }
            Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '06  /  ДИАГНОСТИКА И СТАТУС'; }
            Alert { width: 820; height: 70; tone: 'success'; text: 'Разметка проверена. Ошибок нет.'; description: 'StudioControls.ui'; }
            Alert { width: 820; height: 70; tone: 'warning'; text: 'Содержимое выходит за границы Frame'; description: 'Inspector.ui:24'; }
            Alert { width: 820; height: 70; tone: 'danger'; text: 'Ключ capton не найден. Возможно, caption?'; description: 'LargeButton.ui:8'; }
            StatusBar { width: 820; first: 'Сохранено'; second: 'Forma UI'; third: 'UTF-8'; }
          }
        }
    }
}

component StudioTabs {
    Column {
        width: 880; height: 360; padding: 24; gap: 10; background: state.theme.canvas;
        Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '02  /  ВКЛАДКИ РЕДАКТОРА'; }
        Row { gap: 2; height: 36;
            TabButton { width: 170; text: 'SearchWindow.ui'; selected: true; clicked -> actions.selectTab(); }
            TabButton { width: 170; text: 'Button.ui •'; }
            TabButton { width: 170; text: 'tokens.ui'; }
            TabButton { width: 170; text: 'README.md'; disabled: true; }
        }
    }
}

component StudioToggles {
    Column {
        width: 880; height: 360; padding: 24; gap: 10; background: state.theme.canvas;
        Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '05  /  ПАРАМЕТРЫ ПРЕДПРОСМОТРА'; }
        Row { gap: 12; height: 32;
            Checkbox { text: 'Показать размеры'; checked: true; }
            Checkbox { text: 'Привязки к сетке'; }
            Checkbox { text: 'Только чтение'; checked: true; disabled: true; }
        }
    }
}

component StudioToolbar {
    Column {
        width: 880; height: 360; padding: 24; gap: 10; background: state.theme.canvas;
        Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '01  /  ПАНЕЛЬ ИНСТРУМЕНТОВ'; }
        Row { gap: 8; height: 32;
            PrimaryButton { width: 130; text: 'Запустить'; clicked -> actions.run(); }
            SecondaryButton { width: 130; text: 'Открыть'; clicked -> actions.open(); }
            SecondaryButton { width: 130; text: 'Экспорт'; clicked -> actions.export(); }
            SecondaryButton { width: 130; text: 'Остановить'; disabled: true; }
            IconButton { icon: 'assets/plus.svg'; clicked -> actions.add(); }
            IconButton { icon: 'assets/search.svg'; clicked -> actions.search(); }
            IconButton { icon: 'assets/close.svg'; clicked -> actions.close(); }
        }
    }
}

component StudioTree {
    Column {
        width: 880; height: 360; padding: 24; gap: 10; background: state.theme.canvas;
        Surface { width: 820; height: 30; borderWidth: 0; revealWidth: 0; background: #00000000; text: '03  /  ДЕРЕВО ПРОЕКТА'; }
        Row { gap: 18; height: 90;
            Column { width: 270; gap: 2;
                TreeItem { text: 'components'; branch: true; expanded: true; }
                TreeItem { text: 'Button.ui'; branch: false; indent: 18; selected: true; }
                TreeItem { text: 'TextField.ui'; branch: false; indent: 18; }
            }
            Column { width: 270; gap: 2;
                TreeItem { text: 'ui'; branch: true; expanded: false; }
                TreeItem { text: 'assets'; branch: true; expanded: true; }
                TreeItem { text: 'search.svg'; branch: false; indent: 18; disabled: true; }
            }
        }
    }
}

// Passive inline message. Dialog focus, live announcements and actions are separate.
component Alert : Surface {
    width: 360;
    height: 76;
    radius: 12;
    text: 'Токены обновлены';
    description: 'Светлая и тёмная тема готовы.';
    descriptionColor: state.theme.textMuted;
    descriptionFontSize: 12;
    iconSize: 20;
    tone: 'accent';
    match props.tone {
        'success' => {
            background: state.theme.successWash;
            borderColor: state.theme.success;
            icon: 'assets/check-circle.svg';
        }
        'warning' => {
            background: state.theme.warningWash;
            borderColor: state.theme.warning;
            icon: 'assets/warning.svg';
        }
        'danger' => {
            background: state.theme.dangerWash;
            borderColor: state.theme.dangerInk;
            icon: 'assets/error.svg';
        }
        _ => {
            background: state.theme.accentWash;
            borderColor: state.theme.accentInk;
            icon: 'assets/info.svg';
        }
    }

    override content: MessageContent {
        forward props { icon, iconSize, text, fontSize, description, descriptionColor, descriptionFontSize };
        iconColor: props.borderColor;
        color: props.textColor;
    };
}

// Passive initials avatar; menu and profile navigation belong to an owner.
component Avatar : Surface {
    width: 36;
    height: 36;
    radius: 18;
    borderWidth: 0;
    text: 'TM';
    fontSize: 12;
    background: state.theme.primary;
    color: state.theme.primaryText;
}

// Passive status label. A badge does not toggle or accept focus.
component Badge : Surface {
    width: 84;
    height: 22;
    radius: 11;
    fontSize: 11;
    borderWidth: 0;
    horizontalPadding: 10;
    text: 'Статус';
    tone: 'neutral';
    background: match props.tone {
        'accent' => state.theme.accentWash;
        'success' => state.theme.successWash;
        'warning' => state.theme.warningWash;
        'danger' => state.theme.dangerWash;
        _ => state.theme.surfaceHover;
    };
    color: match props.tone {
        'accent' => state.theme.accentInk;
        'success' => state.theme.success;
        'warning' => state.theme.warning;
        'danger' => state.theme.dangerInk;
        _ => state.theme.textMuted;
    };
}

// Single line visual part with left alignment; wrapping is a text-engine concern.
component BodyText {
    text: ''; color: state.theme.textMuted; fontSize: 13;
    Frame { columns: [auto, *]; padding: 0;
        Label { cell: 1 1; text: props.text; color: props.color; fontSize: props.fontSize; }
    }
}

// Interactive base. Visual variants inherit this single action surface.
component Button : Surface {
    width: 160;
    height: 32;
    radius: 8;
    fontSize: 14;
    borderWidth: 1;
    horizontalPadding: 12;
    iconSize: 16;
    text: 'Кнопка';
    background: state.theme.surfaceRaised;
    hoverBackground: state.theme.surfaceHover;
    pressedBackground: state.theme.surfacePressed;
    disabledBackground: state.theme.surface;
    disabledBorderColor: state.theme.border;
    focusBorderColor: state.theme.focus;

    override interaction: PointerArea {
        clicked -> events.clicked();
    };
}

// Passive card surface. Supply its content slot with reusable visual components.
component Card : Surface {
    width: 320;
    height: 180;
    radius: 14;
    text: '';
    background: state.theme.surface;
    borderColor: state.theme.border;
}

// Passive check glyph, shared by choice indicators and selected menu items.
component CheckMark : Icon {
    source: 'assets/check.svg';
    width: 12;
    height: 12;
    color: state.theme.primary;
}

// checked/indeterminate are explicit snapshot values; the host owns updates.
component Checkbox : Button {
    width: 240;
    height: 32;
    text: 'Параметр';
    checked: false;
    indeterminate: false;
    round: false;
    background: #00000000;
    hoverBackground: #00000000;
    pressedBackground: #00000000;
    disabledBackground: #00000000;
    borderWidth: 0;
    focusBorderColor: #00000000;
    borderColor: #00000000;
    disabledBorderColor: #00000000;
    markColor: match props.disabled {
        true => state.theme.textDisabled;
        _ => state.theme.primary;
    };
    indicatorBorder: match props.disabled {
        true => state.theme.border;
        _ => state.theme.borderStrong;
    };

    override reveal: Reveal {
        width: 1;
        color: props.revealColor;
        targetX: 10;
        targetWidth: 18;
        targetHeight: 18;
        targetRadius: match props.round { true => 9; _ => 5; };
        radius: 120;
        stop: 0.6;
        activeRadius: 1200;
        activeStop: 0.99;
        transition: state.motion.reveal;
    };

    override content: ChoiceContent {
        checked: props.checked;
        indeterminate: props.indeterminate;
        round: props.round;
        text: props.text;
        color: props.textColor;
        markColor: props.markColor;
        indicatorBorder: props.indicatorBorder;
        fontSize: props.fontSize;
    };
}

// Selectable chip snapshot; distinct from passive Badge.
component Chip : Button {
    width: 84;
    height: 28;
    radius: 14;
    fontSize: 12;
    text: 'Метка';
    selected: false;
    background: match props.selected {
        true => state.theme.primary;
        _ => #00000000;
    };
    hoverBackground: match props.selected {
        true => state.theme.primaryHover;
        _ => state.theme.surfaceHover;
    };
    pressedBackground: match props.selected {
        true => state.theme.primaryPressed;
        _ => state.theme.surfacePressed;
    };
    borderColor: match props.selected {
        true => state.theme.primary;
        _ => state.theme.border;
    };
    color: match props.selected {
        true => state.theme.primaryText;
        _ => state.theme.textMuted;
    };
    focusBorderColor: match props.selected {
        true => state.theme.primaryText;
        _ => state.theme.focus;
    };
}

// Passive indicator + label composition for Checkbox and RadioButton.
component ChoiceContent {
    checked: false;
    indeterminate: false;
    round: false;
    text: '';
    color: state.theme.text;
    markColor: state.theme.primary;
    indicatorBackground: state.theme.surface;
    indicatorBorder: state.theme.borderStrong;
    fontSize: 14;

    Frame {
        columns: [18, *];
        padding: 0 10;
        gap: 10;
        ChoiceIndicator {
            cell: 1 1;
            checked: props.checked;
            indeterminate: props.indeterminate;
            round: props.round;
            color: props.markColor;
            background: props.indicatorBackground;
            borderColor: props.indicatorBorder;
        }
        StartLabel {
            cell: 1 2;
            text: props.text;
            color: props.color;
            fontSize: props.fontSize;
        }
    }
}

// Passive snapshot of a checkbox/radio mark. No independent input target.
component ChoiceIndicator {
    checked: false;
    indeterminate: false;
    round: false;
    borderColor: state.theme.borderStrong;
    background: state.theme.surface;
    color: state.theme.primary;

    Frame {
        width: 18;
        height: 18;
        Rectangle {
            radius: match props.round { true => 9; _ => 5; };
            background: props.borderColor;
            Rectangle {
                width: 16;
                height: 16;
                radius: match props.round { true => 8; _ => 4; };
                background: props.background;
                ContentPresenter {
                    key: 'mark';
                    content: match (props.indeterminate, props.checked, props.round) {
                        (true, _, false) => Rectangle {
                            width: 10; height: 2; radius: 1;
                            background: props.color;
                        };
                        (_, true, true) => Rectangle {
                            width: 8; height: 8; radius: 4;
                            background: props.color;
                        };
                        (_, true, false) => CheckMark { color: props.color; };
                        _ => Frame {};
                    };
                }
            }
        }
    }
}

// Logical source line; syntax tokens can replace the content slot independently.
component CodeLine : TableRow {
    first: '1'; second: ''; third: ''; text: '';
    number: '1'; height: 24; fontSize: 12;
    override content: Frame {
        columns: [30, *]; padding: 0 8; gap: 8;
        Label { cell: 1 1; text: props.number; fontSize: props.fontSize; color: state.theme.textMuted; }
        BodyText { cell: 1 2; text: props.text; fontSize: props.fontSize; color: props.textColor; }
    };
}

component ColorSwatch : Surface {
    width: 64; height: 40; radius: 8;
    background: state.theme.primary;
}

component DangerButton : Button {
    background: state.theme.danger;
    hoverBackground: state.theme.dangerHover;
    pressedBackground: state.theme.dangerPressed;
    color: state.theme.dangerText;
    borderColor: state.theme.danger;
    focusBorderColor: state.theme.dangerText;
}

// Actions are sibling Button instances managed by the Dialog composition.
component DialogSurface : Surface {
    width: 420; height: 230; radius: 14;
    background: state.theme.surfaceRaised;
}

component DisclosureHeader : SelectTrigger {
    value: 'Параметры'; width: 304; height: 40;
    background: state.theme.surfaceRaised;
}

component EmptyState : Alert {
    text: 'Здесь пока пусто'; description: 'Добавьте первый документ';
    background: state.theme.surface; borderColor: state.theme.border;
    icon: 'assets/info.svg';
}

// Passive field skin: optional leading icon, value/placeholder and suffix.
component FieldContent {
    value: '';
    placeholder: 'Введите текст';
    color: state.theme.text;
    placeholderColor: state.theme.textMuted;
    fontSize: 15;
    showIcon: false;
    icon: 'assets/search.svg';
    iconSize: 16;
    suffix: '';

    Frame {
        padding: 0 12;
        ContentPresenter {
            key: 'body';
            Row {
                gap: 8;
                if props.showIcon {
                    Icon {
                        source: props.icon;
                        color: props.placeholderColor;
                        width: props.iconSize;
                        height: props.iconSize;
                    }
                }
                FieldValue {
                    width: *;
                    forward props { value, placeholder, color, placeholderColor, fontSize };
                }
                Label {
                    text: props.suffix;
                    color: props.placeholderColor;
                    fontSize: 11;
                }
            }
        }
    }
}

// TextInput editing and rendering are provided by the shared Rust runtime.
component FieldValue {
    value: '';
    placeholder: 'Введите текст';
    color: state.theme.text;
    placeholderColor: state.theme.textMuted;
    fontSize: 15;

    Frame {
        TextInput {
            value: props.value;
            placeholder: props.placeholder;
            color: props.color;
            placeholderColor: props.placeholderColor;
            fontSize: props.fontSize;
        }
    }
}

component FormattingButton : SegmentButton {
    width: 32; height: 30; text: 'B';
}

component GhostButton : Button {
    background: #00000000;
    hoverBackground: state.theme.surfaceHover;
    pressedBackground: state.theme.surfacePressed;
    disabledBackground: #00000000;
    color: state.theme.textMuted;
    borderColor: #00000000;
    disabledBorderColor: #00000000;
}

// Passive vector artwork. The owning control supplies its accessible text.
component Icon {
    source: 'assets/search.svg';
    color: state.theme.text;
    width: 16;
    height: 16;

    Image {
        source: props.source;
        color: props.color;
        width: props.width;
        height: props.height;
    }
}

// text names the action even when only its icon is painted.
component IconButton : Button {
    width: 32;
    height: 32;
    text: 'Поиск';
    icon: 'assets/search.svg';

    override content: Icon {
        source: props.icon;
        color: props.textColor;
        width: props.iconSize;
        height: props.iconSize;
    };
}

// Passive composition shared by leading-icon button variants.
component IconLabel {
    icon: 'assets/search.svg';
    iconSize: 16;
    horizontalPadding: 12;
    text: '';
    color: state.theme.text;
    fontSize: 14;

    Frame {
        columns: [*, auto, *];
        gap: 0;
        padding: 0 props.horizontalPadding;
        Frame {
            cell: 1 2;
            columns: [props.iconSize, auto];
            gap: 8;
            padding: 0;
            Icon {
                cell: 1 1;
                source: props.icon;
                color: props.color;
                width: props.iconSize;
                height: props.iconSize;
            }
            Label {
                cell: 1 2;
                text: props.text;
                color: props.color;
                fontSize: props.fontSize;
            }
        }
    }
}

// Passive keyboard-shortcut label; this component does not register a hotkey.
component Keycap : Surface {
    width: 40;
    height: 24;
    radius: 5;
    fontSize: 11;
    text: 'Ctrl';
    background: state.theme.surfaceRaised;
    borderColor: state.theme.borderStrong;
}

// Passive visual leaf. No independent input handling.
component Label {
    text: '';
    color: state.theme.text;
    fontSize: 14;

    Text {
        text: props.text;
        color: props.color;
        fontSize: props.fontSize;
    }
}

component LeadingIconButton : Button {
    icon: 'assets/search.svg';
    text: 'Найти';

    override content: IconLabel {
        icon: props.icon;
        iconSize: props.iconSize;
        horizontalPadding: props.horizontalPadding;
        text: props.text;
        color: props.textColor;
        fontSize: props.fontSize;
    };
}

component LoadingButton : PrimaryIconButton {
    text: 'Загрузка'; icon: 'assets/spinner.svg'; disabled: true;
    disabledBackground: state.theme.primary;
    disabledBorderColor: state.theme.primary;
    textColor: state.theme.primaryText;
}

// One menu row snapshot; its owner closes the popup and updates selected.
component MenuItem : Button {
    width: 220;
    height: 34;
    radius: 6;
    fontSize: 13;
    text: 'Пункт меню';
    selected: false;
    background: match props.selected {
        true => state.theme.surfaceHover;
        _ => #00000000;
    };
    borderColor: #00000000;
    markColor: match props.disabled {
        true => state.theme.textDisabled;
        _ => state.theme.primary;
    };

    override content: Frame {
        columns: [*, 14];
        padding: 0 10;
        gap: 10;
        StartLabel {
            cell: 1 1;
            text: props.text;
            color: props.textColor;
            fontSize: props.fontSize;
        }
        ContentPresenter {
            key: 'selectionMark';
            content: match props.selected {
                true => CheckMark {
                    cell: 1 2;
                    width: 12;
                    height: 12;
                    color: props.markColor;
                };
                _ => Frame { cell: 1 2; };
            };
        }
    };
}

// Passive icon and two text lines. No automatic wrapping or dismissal action.
component MessageContent {
    icon: 'assets/info.svg';
    iconSize: 20;
    iconColor: state.theme.accentInk;
    text: 'Уведомление';
    color: state.theme.text;
    fontSize: 14;
    description: '';
    descriptionColor: state.theme.textMuted;
    descriptionFontSize: 12;

    Frame {
        columns: [props.iconSize, *];
        rows: [22, *];
        gap: 2 10;
        padding: 12;
        Icon {
            cell: 1 1;
            source: props.icon;
            color: props.iconColor;
            width: props.iconSize;
            height: props.iconSize;
        }
        Frame {
            cell: 1 2;
            columns: [-, *];
            Label {
                cell: 1 1;
                text: props.text;
                color: props.color;
                fontSize: props.fontSize;
            }
        }
        Frame {
            cell: 2 2;
            columns: [-, *];
            Label {
                cell: 1 1;
                text: props.description;
                color: props.descriptionColor;
                fontSize: props.descriptionFontSize;
            }
        }
    }
}

// TextInput editing and rendering are provided by the shared Rust runtime.
component MultilineValue {
    value: ''; placeholder: 'Введите текст'; color: state.theme.text;
    placeholderColor: state.theme.textMuted; fontSize: 14;
    Frame { padding: 10 12;
        TextInput {
